"""Feedback parking controller request for the two public-park frontage probes.

The pure policy can be tested on CPU; CARLA actuator wiring remains in the
future Native runner. Positions are engineering coordinates, not legal facts.
"""

from __future__ import annotations

import math

STATIONS_M = {"outside": 12.0, "inside": -10.0}
RATE_HZ = 20
TOTAL_FRAMES = 600


def command(case, frame, observed_x_m, observed_speed_mps):
    if case not in STATIONS_M:
        raise ValueError("Unknown parking target")
    if type(frame) is not int or not 0 <= frame < TOTAL_FRAMES:
        raise ValueError("Frame outside 30-second capture")
    if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x)
           for x in (observed_x_m, observed_speed_mps)):
        raise ValueError("Missing observed Native pose or speed")
    if observed_speed_mps < 0:
        raise ValueError("Negative observed speed")
    remaining = STATIONS_M[case] - observed_x_m
    if remaining < -1.0:
        raise ValueError("Vehicle overshot parking station")
    # The two cases use exactly the same policy; only station changes.
    braking_distance = observed_speed_mps ** 2 / (2 * 2.0) + 1.5
    if remaining <= 0.5:
        return {"throttle": 0.0, "brake": 1.0, "steer": 0.0, "phase": "hold"}
    if remaining <= braking_distance:
        return {"throttle": 0.0, "brake": 0.65, "steer": 0.0, "phase": "brake"}
    return {"throttle": 0.22, "brake": 0.0, "steer": 0.0, "phase": "approach"}


def validate_observed_completion(case, rows):
    if case not in STATIONS_M or len(rows) != TOTAL_FRAMES:
        raise ValueError("Unknown case or incomplete 30-second capture")
    settled = 0
    for index, row in enumerate(rows):
        if row.get("video_frame") != index or abs(row.get("time_s", -1) - index / RATE_HZ) > 1e-6:
            raise ValueError("Frame/time join failed")
        x = row.get("observed_x_m")
        speed = row.get("observed_speed_mps")
        command(case, index, x, speed)
        if abs(x - STATIONS_M[case]) <= 0.5 and speed <= 0.1:
            settled += 1
        elif index >= 100:
            raise ValueError("Parking target not continuously held")
    if settled < TOTAL_FRAMES - 100:
        raise ValueError("Parking interval too short")
    return {"case": case, "captured_frames": TOTAL_FRAMES, "settled_frames": settled,
            "physical_completion_observed": True, "legal_compliance": "unassessed"}

"""Measure rest and body overlap with an authored device zone, without legal classification."""
import math

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')
FRAMES = 600


def finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError('Invalid ' + name)
    return float(value)


def measure(zone, observations):
    if len(observations) != FRAMES:
        raise ValueError('Incomplete original 600-frame source join')
    if not isinstance(zone, dict) or any(key not in zone for key in ('min_x', 'max_x', 'min_y', 'max_y')):
        raise ValueError('Missing governed zone geometry')
    if not finite(zone['min_x'], 'zone min x') < finite(zone['max_x'], 'zone max x'):
        raise ValueError('Invalid governed zone geometry')
    first = None
    rest = []
    overlap = []
    prior_native = -1
    for index, row in enumerate(observations):
        native = row.get('native_frame')
        if row.get('video_frame') != index or type(native) is not int or native <= prior_native:
            raise ValueError('Original frame identity gap')
        prior_native = native
        if abs(finite(row.get('time_s'), 'time') - index / 20) > 1e-6:
            raise ValueError('Original frame/time join differs')
        if row.get('source_cameras') != {name: index for name in CAMERAS}:
            raise ValueError('Four source camera join differs')
        speed = finite(row.get('observed_speed_mps'), 'speed')
        footprint = row.get('vehicle_footprint_m')
        if not isinstance(footprint, dict) or speed < 0:
            raise ValueError('Vehicle footprint or speed absent')
        for key in ('min_x', 'max_x', 'min_y', 'max_y'):
            finite(footprint.get(key), 'footprint ' + key)
        stopped = speed <= 0.10
        intersects = (min(footprint['max_x'], zone['max_x']) > max(footprint['min_x'], zone['min_x'])
                      and min(footprint['max_y'], zone['max_y']) > max(footprint['min_y'], zone['min_y']))
        rest.append(stopped)
        overlap.append(intersects)
        if stopped and first is None:
            first = index
    runs = []
    start = None
    for index, stopped in enumerate(rest + [False]):
        if stopped and start is None:
            start = index
        elif not stopped and start is not None:
            runs.append((start, index - 1))
            start = None
    longest = max(runs, key=lambda item: item[1] - item[0], default=None)
    if longest is None or longest[1] - longest[0] + 1 < 100:
        raise ValueError('No measured five-second stationary interval')
    segment = overlap[longest[0]:longest[1] + 1]
    return {'frame_count': FRAMES, 'rate_hz': 20, 'first_rest_frame': first,
            'rest_interval_frames': list(longest), 'rest_duration_s': len(segment) / 20,
            'zone_overlap_during_rest': all(segment), 'zone_overlap_frame_count': sum(segment),
            'legal_compliance': 'unassessed',
            'limitations': ['Authored zone and synthetic pixels do not establish official device authority.',
                            'Rest interval is a measured proxy; stop, stand, park, necessity and directions require independent review.']}

import json
from pathlib import Path
import unittest

from controller import STATIONS_M, command
from geometry import check as geometry_check
from runner import CAMERAS, check, survey


class FakeCarla:
    class LaneType:
        Driving = 'driving'

    class Location:
        def __init__(self, x, y, z):
            self.x, self.y, self.z = x, y, z


class FakeMap:
    def __init__(self, wrong=False):
        self.wrong = wrong

    def get_waypoint(self, loc, **kwargs):
        transform = type('T', (), {'location': loc})()
        return type('WP', (), {'road_id': 1, 'lane_id': 1 if self.wrong else -1,
                               'transform': transform})()


class NativeDraft(unittest.TestCase):
    def test_geometry_controller_and_camera_contract(self):
        config = json.loads(Path('config.json').read_text())
        self.assertEqual(check(config)['frames'], 600)
        self.assertEqual(len(CAMERAS), 4)
        self.assertEqual(geometry_check()['park_bounds_m']['min_x'], -20.0)
        self.assertLess(STATIONS_M['inside'], 0)
        self.assertGreater(STATIONS_M['outside'], 0)
        self.assertEqual(command(config['zone_case'], 0, -80, 0)['phase'], 'approach')
        self.assertEqual(len(survey(FakeCarla, FakeMap())), 5)
        with self.assertRaisesRegex(RuntimeError, 'lane survey failed'):
            survey(FakeCarla, FakeMap(True))


if __name__ == '__main__':
    unittest.main()
